cd /app && cat > output/assets/styles.css <<'CSS'
:root{
  --bg:#ffffff;
  --text:#0b0b10;
  --muted:#5b5f6a;
  --card:#ffffff;
  --border:rgba(20,20,30,.12);
  --shadow: 0 18px 45px rgba(11, 11, 16, 0.12);
  --shadow-soft: 0 14px 30px rgba(11, 11, 16, 0.10);

  --black:#000000;
  --purple:#7638FA;
  --orange:#FF7A00;
  --magenta:#FF2D9A;
  --cyan:#22D3EE;

  --radius:18px;
  --radius-sm:14px;
  --max:1120px;

  --focus: 0 0 0 4px rgba(118,56,250,.22);
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
  color:var(--text);
  background: var(--bg);
  line-height:1.45;
}
img{max-width:100%; display:block}
a{color:inherit; text-decoration:none}

.container{max-width:var(--max); margin:0 auto; padding:0 20px}

.skip-link{
  position:absolute;
  left:-999px;
  top:12px;
  background:#fff;
  border:1px solid var(--border);
  padding:10px 12px;
  border-radius:12px;
  z-index:999;
}
.skip-link:focus{left:12px; outline:none; box-shadow:var(--focus)}

/* Header */
.header{
  position:sticky;
  top:0;
  z-index:50;
  backdrop-filter: blur(12px);
  background: rgba(255,255,255,.75);
  border-bottom:1px solid rgba(20,20,30,.08);
}
.header-inner{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:14px 0;
}
.brand{
  display:flex;
  align-items:center;
  gap:10px;
  font-weight:750;
  letter-spacing:-0.02em;
}
.logo{
  width:32px;
  height:32px;
  border-radius:12px;
  background:
    radial-gradient(120% 120% at 20% 20%, rgba(255,122,0,.95), rgba(255,45,154,.75) 40%, rgba(118,56,250,.95) 75%, rgba(34,211,238,.85));
  box-shadow: 0 12px 28px rgba(118,56,250,.20);
}

.nav{
  display:flex;
  align-items:center;
  gap:18px;
}
.nav a{
  font-size:14px;
  color: rgba(11,11,16,.78);
  padding:10px 10px;
  border-radius:12px;
}
.nav a:hover{background:rgba(118,56,250,.06)}

.actions{display:flex; align-items:center; gap:10px}

.btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:11px 14px;
  border-radius:999px;
  border:1px solid var(--border);
  background:#fff;
  box-shadow: 0 8px 18px rgba(11,11,16,.06);
  font-weight:650;
  font-size:14px;
}
.btn:hover{transform: translateY(-1px)}
.btn:active{transform: translateY(0px)}
.btn.primary{
  border:none;
  color:#0b0b10;
  background:
    radial-gradient(120% 120% at 10% 10%, rgba(255,122,0,.92), rgba(255,45,154,.62) 45%, rgba(118,56,250,.98) 78%);
  box-shadow: 0 18px 40px rgba(118,56,250,.18);
}
.btn.primary span{filter: drop-shadow(0 10px 25px rgba(0,0,0,.15))}

.icon-btn{
  width:42px;
  height:42px;
  border-radius:14px;
  border:1px solid var(--border);
  background:#fff;
  box-shadow: 0 8px 18px rgba(11,11,16,.06);
  display:none;
  align-items:center;
  justify-content:center;
}
.icon-btn:hover{transform: translateY(-1px)}
.icon{
  width:18px;
  height:18px;
  display:inline-block;
}

/* Mobile overlay nav */
.overlay{
  position:fixed;
  inset:0;
  z-index:100;
  background: rgba(11,11,16,.55);
  display:none;
}
.overlay[aria-hidden="false"]{display:block}
.overlay-panel{
  position:absolute;
  right:14px;
  top:14px;
  left:14px;
  max-width: 520px;
  margin:0 auto;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(14px);
  border:1px solid rgba(20,20,30,.10);
  border-radius: 22px;
  padding: 14px;
  box-shadow: var(--shadow);
}
.overlay-top{display:flex; align-items:center; justify-content:space-between; gap:12px; padding:6px 4px 10px}
.overlay-links{display:grid; gap:8px; padding:6px 4px 10px}
.overlay-links a{
  padding:12px 12px;
  border-radius:16px;
  background: rgba(118,56,250,.06);
  border:1px solid rgba(118,56,250,.12);
}
.overlay-links a:hover{background: rgba(118,56,250,.09)}

/* Hero */
.hero{
  position:relative;
  overflow:hidden;
}
.hero::before{
  content:"";
  position:absolute;
  inset:-120px -120px auto -120px;
  height:520px;
  background:
    radial-gradient(40% 55% at 20% 35%, rgba(118,56,250,.26), transparent 62%),
    radial-gradient(55% 60% at 68% 40%, rgba(255,45,154,.20), transparent 60%),
    radial-gradient(55% 60% at 52% 65%, rgba(255,122,0,.18), transparent 60%),
    radial-gradient(40% 60% at 80% 65%, rgba(34,211,238,.16), transparent 65%);
  filter: blur(2px);
}
.hero-inner{position:relative; padding:64px 0 42px; display:grid; grid-template-columns: 1.1fr .9fr; gap:28px; align-items:center}
.kicker{
  display:inline-flex;
  align-items:center;
  gap:10px;
  font-weight:650;
  color: rgba(11,11,16,.72);
  background: rgba(118,56,250,.07);
  border: 1px solid rgba(118,56,250,.12);
  border-radius: 999px;
  padding: 8px 12px;
}
.kicker-dot{
  width:10px;height:10px;border-radius:999px;
  background: linear-gradient(135deg, var(--orange), var(--magenta), var(--purple));
  box-shadow: 0 10px 25px rgba(118,56,250,.18);
}

.h1{
  margin:14px 0 12px;
  font-size: clamp(34px, 4.2vw, 56px);
  letter-spacing:-0.04em;
  line-height:1.02;
}
.lead{margin:0 0 18px; font-size:18px; color: rgba(11,11,16,.75); max-width: 46ch}
.hero-cta{display:flex; gap:12px; align-items:center; flex-wrap:wrap}
.small-note{font-size:13px; color: rgba(11,11,16,.55)}

.hero-art{
  border-radius: 28px;
  border: 1px solid rgba(20,20,30,.10);
  background: linear-gradient(135deg, rgba(118,56,250,.12), rgba(255,45,154,.10), rgba(255,122,0,.10));
  box-shadow: var(--shadow);
  padding: 18px;
}
.art-card{
  border-radius: 22px;
  background: rgba(255,255,255,.82);
  border:1px solid rgba(20,20,30,.10);
  padding: 16px;
}
.art-grid{
  display:grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 12px;
}
.art-tile{
  border-radius: 18px;
  height: 120px;
  border: 1px solid rgba(20,20,30,.10);
  background:
    radial-gradient(90% 90% at 30% 30%, rgba(255,122,0,.65), transparent 60%),
    radial-gradient(80% 80% at 70% 35%, rgba(255,45,154,.55), transparent 62%),
    radial-gradient(75% 75% at 55% 75%, rgba(118,56,250,.65), transparent 62%);
}
.art-tile.alt{
  background:
    radial-gradient(80% 80% at 30% 25%, rgba(34,211,238,.55), transparent 60%),
    radial-gradient(85% 85% at 70% 50%, rgba(118,56,250,.55), transparent 62%),
    radial-gradient(75% 75% at 52% 80%, rgba(255,45,154,.55), transparent 62%);
}

/* Section shell */
.section{padding: 54px 0}
.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:14px; margin-bottom: 18px}
.eyebrow{font-size:13px; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color: rgba(11,11,16,.55)}
.h2{margin:0; font-size: clamp(24px, 2.4vw, 36px); letter-spacing:-0.03em; line-height:1.1}
.p{margin:10px 0 0; color: rgba(11,11,16,.72); max-width: 76ch}

.feature-row{display:grid; grid-template-columns: 1fr 1fr; gap: 18px; align-items:stretch}
.panel{
  border-radius: var(--radius);
  border:1px solid var(--border);
  background: var(--card);
  box-shadow: var(--shadow-soft);
  padding: 18px;
}
.panel.accent{
  background:
    radial-gradient(80% 80% at 12% 18%, rgba(118,56,250,.14), transparent 60%),
    radial-gradient(80% 80% at 75% 25%, rgba(255,45,154,.11), transparent 60%),
    radial-gradient(75% 75% at 50% 85%, rgba(255,122,0,.10), transparent 62%),
    #fff;
}
.panel.soft{
  background:
    radial-gradient(70% 70% at 18% 24%, rgba(34,211,238,.12), transparent 60%),
    radial-gradient(70% 70% at 80% 35%, rgba(118,56,250,.10), transparent 62%),
    #fff;
}

.list{display:grid; gap:10px; margin-top: 14px}
.item{
  display:flex;
  align-items:flex-start;
  gap:10px;
  padding: 12px 12px;
  border-radius: 16px;
  background: rgba(11,11,16,.03);
  border:1px solid rgba(20,20,30,.08);
}
.badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:34px;
  height:34px;
  border-radius: 14px;
  border:1px solid rgba(20,20,30,.10);
  background:
    radial-gradient(120% 120% at 20% 20%, rgba(255,122,0,.70), rgba(255,45,154,.35) 40%, rgba(118,56,250,.65) 75%, rgba(34,211,238,.45));
  flex: 0 0 auto;
}
.badge svg{width:16px;height:16px}

.link{
  display:inline-flex;
  align-items:center;
  gap:8px;
  font-weight:700;
  padding:10px 12px;
  border-radius: 999px;
  border:1px solid rgba(118,56,250,.18);
  background: rgba(118,56,250,.08);
}
.link:hover{background: rgba(118,56,250,.11)}

/* Tagline banner */
.tagline{
  padding: 22px 0;
}
.tagline-inner{
  border-radius: 999px;
  border: 1px solid rgba(20,20,30,.10);
  background:
    radial-gradient(140% 220% at 0% 50%, rgba(118,56,250,.18), transparent 55%),
    radial-gradient(140% 220% at 100% 50%, rgba(255,122,0,.16), transparent 55%),
    rgba(255,255,255,.7);
  backdrop-filter: blur(10px);
  padding: 16px 18px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}
.tagline-inner strong{font-size:15px}

/* News */
.news-top{display:flex; align-items:flex-end; justify-content:space-between; gap:14px; margin-bottom: 14px}
.news-top .left{display:grid; gap:6px}
.news-actions{display:flex; gap:10px; align-items:center}

.carousel{
  position:relative;
  border-radius: 24px;
  border:1px solid rgba(20,20,30,.10);
  background: rgba(255,255,255,.65);
  backdrop-filter: blur(10px);
  padding: 14px;
}
.carousel::before{
  content:"";
  position:absolute;
  inset:0;
  border-radius: 24px;
  pointer-events:none;
  background:
    linear-gradient(90deg, rgba(255,255,255,.92), rgba(255,255,255,0) 12%),
    linear-gradient(270deg, rgba(255,255,255,.92), rgba(255,255,255,0) 12%);
  mask: linear-gradient(90deg, #000, transparent 12%, transparent 88%, #000);
  opacity:.9;
}

.scroller{
  display:flex;
  gap:14px;
  overflow-x:auto;
  scroll-snap-type: x mandatory;
  padding: 8px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scroll-behavior: smooth;
}
.scroller::-webkit-scrollbar{height:10px}
.scroller::-webkit-scrollbar-thumb{background: rgba(11,11,16,.18); border-radius:999px}
.scroller::-webkit-scrollbar-track{background: rgba(11,11,16,.06); border-radius:999px}

.news-card{
  scroll-snap-align: start;
  flex: 0 0 auto;
  width: min(360px, 84vw);
  border-radius: 22px;
  border:1px solid rgba(20,20,30,.12);
  background: #fff;
  box-shadow: 0 16px 40px rgba(11,11,16,.10);
  overflow:hidden;
  display:flex;
  flex-direction:column;
}
.thumb{
  height: 154px;
  background:
    radial-gradient(60% 80% at 20% 30%, rgba(255,122,0,.75), transparent 60%),
    radial-gradient(70% 70% at 70% 40%, rgba(255,45,154,.55), transparent 62%),
    radial-gradient(70% 80% at 55% 80%, rgba(118,56,250,.70), transparent 62%),
    radial-gradient(70% 70% at 85% 70%, rgba(34,211,238,.38), transparent 62%),
    #0b0b10;
}
.thumb.t2{background:
    radial-gradient(65% 80% at 22% 35%, rgba(34,211,238,.55), transparent 60%),
    radial-gradient(80% 80% at 74% 38%, rgba(118,56,250,.55), transparent 62%),
    radial-gradient(80% 80% at 50% 82%, rgba(255,122,0,.52), transparent 62%),
    #0b0b10;
}
.thumb.t3{background:
    radial-gradient(70% 70% at 20% 35%, rgba(255,45,154,.60), transparent 60%),
    radial-gradient(80% 80% at 75% 45%, rgba(255,122,0,.55), transparent 62%),
    radial-gradient(75% 75% at 55% 82%, rgba(118,56,250,.65), transparent 62%),
    #0b0b10;
}
.thumb.t4{background:
    radial-gradient(70% 70% at 22% 28%, rgba(118,56,250,.62), transparent 60%),
    radial-gradient(80% 80% at 74% 45%, rgba(34,211,238,.48), transparent 62%),
    radial-gradient(75% 75% at 55% 82%, rgba(255,45,154,.55), transparent 62%),
    #0b0b10;
}

.news-body{padding: 14px 14px 16px; display:grid; gap:10px}
.tags{display:flex; flex-wrap:wrap; gap:8px}
.tag{
  font-size: 12px;
  font-weight:750;
  letter-spacing:.02em;
  padding:6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(118,56,250,.18);
  background: rgba(118,56,250,.08);
  color: rgba(11,11,16,.8);
}
.tag.safety{border-color: rgba(34,211,238,.22); background: rgba(34,211,238,.10)}
.tag.product{border-color: rgba(255,122,0,.22); background: rgba(255,122,0,.10)}
.tag.announce{border-color: rgba(255,45,154,.22); background: rgba(255,45,154,.10)}

.news-title{font-weight:780; letter-spacing:-0.02em; line-height:1.18}
.news-meta{font-size:13px; color: rgba(11,11,16,.58)}

.carousel-controls{
  display:flex;
  gap:10px;
  justify-content:flex-end;
  padding: 10px 6px 2px;
}
.control{
  border:1px solid rgba(20,20,30,.12);
  background:#fff;
  border-radius: 14px;
  width:42px;
  height:42px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  box-shadow: 0 10px 18px rgba(11,11,16,.06);
}
.control:hover{transform: translateY(-1px)}

/* CTA Download */
.cta{
  border-radius: 28px;
  border:1px solid rgba(20,20,30,.10);
  background:
    radial-gradient(80% 80% at 18% 35%, rgba(118,56,250,.16), transparent 60%),
    radial-gradient(80% 80% at 80% 45%, rgba(255,122,0,.14), transparent 60%),
    radial-gradient(80% 80% at 60% 80%, rgba(255,45,154,.12), transparent 62%),
    #fff;
  box-shadow: var(--shadow);
  padding: 26px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
}
.cta h3{margin:0; font-size:28px; letter-spacing:-0.03em; line-height:1.1}
.cta p{margin:6px 0 0; color: rgba(11,11,16,.72)}

.store-buttons{display:flex; gap:10px; flex-wrap:wrap}
.store{
  display:inline-flex;
  align-items:center;
  gap:10px;
  padding: 12px 14px;
  border-radius: 18px;
  border:1px solid rgba(20,20,30,.12);
  background:#fff;
  box-shadow: 0 12px 22px rgba(11,11,16,.08);
}
.store strong{display:block; font-size:14px}
.store span{display:block; font-size:12px; color: rgba(11,11,16,.62)}
.store svg{width:22px;height:22px}

/* Footer */
.footer{padding: 54px 0 28px; border-top:1px solid rgba(20,20,30,.10); background: rgba(11,11,16,.02)}
.footer-grid{
  display:grid;
  grid-template-columns: 1.3fr 1fr 1fr 1fr 1fr;
  gap: 18px;
  align-items:start;
}
.footer h4{margin:0 0 10px; font-size:13px; letter-spacing:.08em; text-transform:uppercase; color: rgba(11,11,16,.55)}
.footer a{color: rgba(11,11,16,.74)}
.footer a:hover{color: rgba(11,11,16,.92)}
.footer ul{list-style:none; padding:0; margin:0; display:grid; gap:8px}
.footer-brand p{margin:10px 0 0; color: rgba(11,11,16,.68)}
.footer-bottom{
  display:flex;
  justify-content:space-between;
  gap:14px;
  align-items:center;
  margin-top: 26px;
  padding-top: 18px;
  border-top: 1px solid rgba(20,20,30,.10);
  flex-wrap:wrap;
}
.select{
  border:1px solid rgba(20,20,30,.14);
  background:#fff;
  border-radius: 14px;
  padding: 10px 12px;
}
.social{display:flex; gap:10px; flex-wrap:wrap; align-items:center}
.social a{
  width:40px; height:40px;
  border-radius: 14px;
  border:1px solid rgba(20,20,30,.12);
  background:#fff;
  display:inline-flex;
  align-items:center;
  justify-content:center;
}
.social svg{width:18px;height:18px; opacity:.75}
.legal{display:flex; gap:12px; flex-wrap:wrap; color: rgba(11,11,16,.62)}
.legal a{color: rgba(11,11,16,.62)}
.legal a:hover{color: rgba(11,11,16,.85)}

/* Accessibility helpers */
:focus-visible{outline:none; box-shadow:var(--focus)}

/* Responsive */
@media (max-width: 980px){
  .hero-inner{grid-template-columns: 1fr; padding: 50px 0 28px}
  .feature-row{grid-template-columns: 1fr}
  .footer-grid{grid-template-columns: 1fr 1fr;}
  .icon-btn{display:inline-flex}
  .nav{display:none}
}
@media (max-width: 520px){
  .footer-grid{grid-template-columns: 1fr}
  .cta{flex-direction:column; align-items:flex-start}
  .tagline-inner{border-radius: 22px; flex-direction:column; align-items:flex-start}
}

@media (prefers-reduced-motion: reduce){
  *{scroll-behavior:auto !important; transition:none !important}
  .btn:hover,.icon-btn:hover,.control:hover{transform:none}
}
